/// Raven `G_PointInBounds`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:1877-1894`
pub fn G_PointInBounds(
    point: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
) -> qboolean {
    for i in 0..3 {
        if point[i] < mins[i] {
            return qfalse;
        }
        if point[i] > maxs[i] {
            return qfalse;
        }
    }
    qtrue
}

/// Raven `G_BoxInBounds`.
///
/// Source: `oracle/oracle/codemp/game/g_utils.c:1896-1924`
pub fn G_BoxInBounds(
    point: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
    boundsMins: vec3_t,
    boundsMaxs: vec3_t,
) -> qboolean {
    let boxMins = [point[0] + mins[0], point[1] + mins[1], point[2] + mins[2]];
    let boxMaxs = [point[0] + maxs[0], point[1] + maxs[1], point[2] + maxs[2]];

    if boxMaxs[0] > boundsMaxs[0] {
        return qfalse;
    }
    if boxMaxs[1] > boundsMaxs[1] {
        return qfalse;
    }
    if boxMaxs[2] > boundsMaxs[2] {
        return qfalse;
    }
    if boxMins[0] < boundsMins[0] {
        return qfalse;
    }
    if boxMins[1] < boundsMins[1] {
        return qfalse;
    }
    if boxMins[2] < boundsMins[2] {
        return qfalse;
    }

    // box is completely contained within bounds
    qtrue
}

